	return boxes[i].Style.ZIndex < boxes[j].Style.ZIndex
})

switch msg := msg.(type) {
case tea.KeyMsg:
	switch msg.String() {
	case "ctrl+c", "q":
		return m, tea.Quit
	case "tab", "shift+tab":
		return m, nil
	}
case pageLoadedMsg:
	if t := m.active(); t != nil {
		t.ANSILines = msg.ANSI
		t.ASCIILines = msg.Lines
	}
	m.loadedPageContent = strings.Join(msg.Lines, "\n")
	m.Mode = ModeView
	return m, nil
case pageErrorMsg:
	if t := m.active(); t != nil {
		t.Err = msg.Err
		t.Mode = ModeError
	}
	m.Mode = ModeError
	return m, nil
case tickMsg:

	return m, nil
}

switch msg.String() {
case "ctrl+c", "q":
	return m, tea.Quit
case "tab", "shift+tab":
	return m, nil
}

switch m.Mode {
case ModeLoading:
	b.WriteString("\n" + center("Loading...", m.Width))
case ModeError:
	errMsg := fmt.Sprintf("Error: %v", m.Err())
	b.WriteString("\n" + center(errMsg, m.Width))
	b.WriteString("\n" + center("Press Ctrl+L to edit URL or Q to quit", m.Width))
case ModeAddress:
	b.WriteString("\n" + center(m.Address.Value(), m.Width))
case ModeView:
	lines := m.ANSILines()
	yoff := m.Viewport.YOffset
	h := m.Viewport.Height
	if h <= 0 {
		h = 24
	}
	if yoff >= len(lines) {
		yoff = len(lines) - h
		if yoff < 0 {
			yoff = 0
		}
	}
	end := yoff + h
	if end > len(lines) {
		end = len(lines)
	}
	visible := lines[yoff:end]

	w := m.Width
	if w <= 0 {
		w = 80
	}
	offsetX := m.OffsetX()
	for i, line := range visible {
		runes := []rune(line)
		start := offsetX
		if start >= len(runes) {
			visible[i] = ""
		} else {
			end := start + w
			if end > len(runes) {
				end = len(runes)
			}
			visible[i] = string(runes[start:end])
		}

		visible[i] = strings.TrimRight(visible[i], " ")
	}
	result := strings.Join(visible, "\n")
	b.WriteString(result)
}

switch prop {
case "color":
	style.Color = parseColor(val)
case "background-color":
	style.BackgroundColor = parseColor(val)
}

switch val {
case "hidden":
	return OverflowHidden
case "visible":
	return OverflowVisible
}

switch len(parts) {
case 1:
	l := parseLength(parts[0])
	return BoxModel{Top: l, Right: l, Bottom: l, Left: l}
case 2:
	v := parseLength(parts[0])
	h := parseLength(parts[1])
	return BoxModel{Top: v, Right: h, Bottom: v, Left: h}
case 3:
	t := parseLength(parts[0])
	h := parseLength(parts[1])
	b := parseLength(parts[2])
	return BoxModel{Top: t, Right: h, Bottom: b, Left: h}
case 4:
	return BoxModel{
		Top:    parseLength(parts[0]),
		Right:  parseLength(parts[1]),
		Bottom: parseLength(parts[2]),
		Left:   parseLength(parts[3]),
	}
}

switch part {
case "none":
	b.Style = BorderNone
case "solid":
	b.Style = BorderSolid
default:
	if strings.HasSuffix(part, "px") || isNumber(part) {
		b.Width, _ = strconv.ParseFloat(strings.TrimSuffix(part, "px"), 64)
		if b.Width == 0 && isNumber(part) {
			b.Width, _ = strconv.ParseFloat(part, 64)
		}
	} else {
		b.Color = parseColor(part)
	}
}

switch val {
case "none":
	return BorderNone
case "solid":
	return BorderSolid
}

switch val {
case "row":
	return FlexDirectionRow
case "column":
	return FlexDirectionColumn
}

switch tt {
case html.ErrorToken:
	return doc

case html.TextToken:
	handleTextToken(stack, tokenizer)

case html.StartTagToken, html.SelfClosingTagToken:
	stack = handleStartTag(stack, tokenizer, tt)

case html.EndTagToken:
	if len(stack) > 1 {
		stack = stack[:len(stack)-1]
	}
}

switch s[i] {
case '*':
	if first {
		part.Tag = "*"
		i++
		first = false
	} else {
		return part, i, nil
	}
case '#':
	id, n := parseHash(s[i:])
	part.ID = id
	i += n
	first = false
case '.':
	class, n := parseClass(s[i:])
	part.Classes = append(part.Classes, class)
	i += n
	first = false
case '[':
	attr, n, err := parseAttribute(s[i:])
	if err != nil {
		return part, i, err
	}
	if n == 0 {
		return part, i, fmt.Errorf("invalid attribute selector near %q", s[i:])
	}
	part.Attributes = append(part.Attributes, attr)
	i += n
	first = false
case ':':
	pseudo, n, err := parsePseudo(s[i:])
	if err != nil {
		return part, i, err
	}
	part.Pseudos = append(part.Pseudos, pseudo)
	i += n
	first = false
case '>', '+', '~', ',':
	return part, i, nil
default:
	if first {
		tag, n := parseIdent(s[i:])
		if n == 0 {
			return part, i, nil
		}
		part.Tag = tag
		i += n
		first = false
	} else {
		return part, i, nil
	}
}

switch s[i] {
case ']':

case '=':
	attr.Op = "="
	i++
case '~':
	if i+1 < len(s) && s[i+1] == '=' {
		attr.Op = "~="
		i += 2
	} else {
		return attr, i, nil
	}
case '|':
	if i+1 < len(s) && s[i+1] == '=' {
		attr.Op = "|="
		i += 2
	} else {
		return attr, i, nil
	}
case '^':
	if i+1 < len(s) && s[i+1] == '=' {
		attr.Op = "^="
		i += 2
	} else {
		return attr, i, nil
	}
case '$':
	if i+1 < len(s) && s[i+1] == '=' {
		attr.Op = "$="
		i += 2
	} else {
		return attr, i, nil
	}
case '*':
	if i+1 < len(s) && s[i+1] == '=' {
		attr.Op = "*="
		i += 2
	} else {
		return attr, i, nil
	}
default:
	return attr, i, nil
}

switch s[i] {
case '(':
	depth++
case ')':
	depth--
}

switch comb {
case " ", "":

	for anc := n.Parent; anc != nil; anc = anc.Parent {
		if matchPart(anc, parts, idx-1) {
			return true
		}
	}
case ">":
	if n.Parent != nil && matchPart(n.Parent, parts, idx-1) {
		return true
	}
case "+":
	prev := previousElementSibling(n)
	if prev != nil && matchPart(prev, parts, idx-1) {
		return true
	}
case "~":
	for prev := previousElementSibling(n); prev != nil; prev = previousElementSibling(prev) {
		if matchPart(prev, parts, idx-1) {
			return true
		}
	}
}

switch attr.Op {
case "":
	return exists
case "=":
	return val == attr.Value
case "~=":
	for _, f := range strings.Fields(val) {
		if f == attr.Value {
			return true
		}
	}
	return false
case "|=":
	return val == attr.Value || strings.HasPrefix(val, attr.Value+"-")
case "^=":
	return strings.HasPrefix(val, attr.Value)
case "$=":
	return strings.HasSuffix(val, attr.Value)
case "*=":
	return strings.Contains(val, attr.Value)
}

switch arg {
case "even":
	return idx%2 == 0
case "odd":
	return idx%2 == 1
}

switch aStr {
case "":
	a = 1
case "-":
	a = -1
default:
	v, err := strconv.Atoi(aStr)
	if err != nil {
		return 0, 0, false
	}
	a = v
}
